BEGIN;
ALTER TABLE public.leads_prospeccao DROP CONSTRAINT IF EXISTS leads_prospeccao_origem_check;
ALTER TABLE public.leads_prospeccao ADD CONSTRAINT leads_prospeccao_origem_check CHECK (origem IN ('manual', 'csv', 'osm', 'integracao_futura'));
CREATE TABLE IF NOT EXISTS public.prospeccao_regioes (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome text NOT NULL, pais text NOT NULL DEFAULT '', cidade text NOT NULL DEFAULT '', bairro text NOT NULL DEFAULT '', latitude numeric(9,6) NOT NULL, longitude numeric(9,6) NOT NULL, raio_metros integer NOT NULL DEFAULT 5000, ativa boolean NOT NULL DEFAULT true, ultima_busca timestamptz, criado_em timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, criado_por integer REFERENCES public.usuarios(id) ON DELETE SET NULL, CONSTRAINT prospeccao_regioes_raio_check CHECK (raio_metros BETWEEN 100 AND 50000), CONSTRAINT prospeccao_regioes_coord_check CHECK (latitude BETWEEN -90 AND 90 AND longitude BETWEEN -180 AND 180));
CREATE INDEX IF NOT EXISTS prospeccao_regioes_ativas_idx ON public.prospeccao_regioes (ativa, id);
COMMIT;
